/**
 * 五、对话题: each dialogue is a list of lines; a line with `blank` is the one
 * to write. `ok` holds patterns tested against the answer with spaces and
 * punctuation removed; `sample` is shown after checking.
 */
export interface DialogueBlank { ok: string[]; sample: { zh: string; py: string; ru: string; en: string }[] }
export interface DialogueLine { who: 'A' | 'B'; zh?: string; py?: string; pre?: string; blank?: DialogueBlank; end?: string }
const s = (zh: string, py: string, ru: string, en: string) => ({ zh, py, ru, en });

